  _ = `Este convite foi cancelado`,
  _ = `Como funcionam os convites?`,
  _ = `Se o seu jogo for convidado a participar numa Promoção Diária, irá receber um e-mail e poderá ver o seu jogo listado acima. Eis como funciona o processo a partir desse ponto:`,
  _ = `Selecione uma data disponível, dentro dos próximos seis meses, que lhe seja conveniente.`,
  _ = `A visibilidade do jogo na página inicial do Steam e nas páginas de marcadores aplicáveis estará ativa durante 24 horas. O desconto, porém, estará ativo durante 7-14 dias, dependendo da duração selecionada do desconto. A promoção irá começar na data que selecionar às 10h no fuso horário do Pacífico.`,
  _ = `Quando selecionar uma data disponível, ser-lhe-á pedido para introduzir a percentagem do desconto e selecionar os pacotes que gostaria de incluir na promoção.`,
  _ = `Pedimos-lhe que escolha uma percentagem idêntica à do melhor desconto que o jogo teve no passado (ou até mais alta do que isso).`,
  _ = `Se não puder agendar a sua Promoção Diária agora mesmo, o convite estará no painel de Promoções Diárias. Não se esqueça da data de expiração.`,
  _ = `Se tiver alguma dúvida ou se precisar de alterar a data ou cancelar - %1$s`,
  _ = `Entre em contacto connosco aqui`,
  _ = `Boas práticas de Promoções Diárias`,
  _ = `É normalmente vantajoso tirar proveito desta maior visibilidade e ter o desconto ativo ao mesmo tempo que outras atividades que tenha planeado, como uma atualização do conteúdo do seu jogo, um stream em direto ou um evento comunitário.`,
  _ = `Se agendou outros descontos para o seu jogo num prazo de um mês antes da sua Promoção Diária selecionada, tente manter a percentagem igual à usada nesses descontos. Quando um jogo faz parte de uma Promoção Diária, preferimos que o desconto seja tão bom ou melhor do que um que tenha disponibilizado no passado.`,
