  _ = `Anti-cheats`,
  _ = `Se o seu jogo instalar software anti-cheats ao nível do kernel no computador dos utilizadores, terá de divulgar esse facto. Pode fazê-lo aqui. Caso tenha a sua própria solução anti-cheats, ou se a sua solução não estiver na lista abaixo, selecione "Outra solução anti-cheats" e introduza as suas informações.`,
  _ = `Se o seu jogo contiver software anti‑cheats baseado no cliente ou num servidor que não seja ao nível do kernel, preencher este campo é opcional, mas acreditamos que qualquer jogo que utilize tecnologia anti‑cheats beneficia quando os utilizadores estão conscientes do que estão a instalar.`,
