  _ = `(Na página "Editar pacote da loja" abaixo, pode editar a lista de imagens de cápsula deste pacote que pretende apresentar.)`,
  _ = `Esta definição irá apresentar as imagens de cápsula na opção de compra do pacote na loja, semelhante à forma como os conteúdos de conjuntos são apresentados. A cápsula da aplicação base será mostrada primeiro, seguida pelas cápsulas das outras aplicações incluídas, ordenadas por preço decrescente.`,
  _ = `Omitir nome do jogo do início do nome de artigos na lista de conteúdo do pacote.`,
  _ = `Para reduzir a redundância e melhorar a legibilidade, esta opção omite o nome do jogo, espaços em branco e sinais gráficos (como dois pontos e hífenes) do início de artigos como DLCs e bandas sonoras quando estiverem listados na área de compra do pacote. Por exemplo, "Half-Life 2: Episode 1" irá aparecer como "Episode 1". Só o nome exato do jogo base, espaços em branco e sinais gráficos comuns (como hífenes e dois pontos) são omitidos.`,
