  _ = `Estes preços não podem ser enviados enquanto não forem corrigidos. Para mais informações, consulte a documentação sobre <1>preços</1>.`,
  _ = `Com base no seu método de conversão selecionado e no preço em USD, o preço introduzido é muito mais alto do que o sugerido (%1$s).`,
  _ = `Com base no seu método de conversão selecionado e no preço em USD, o preço introduzido é muito mais baixo do que o sugerido (%1$s).`,
  _ = `Com base no seu método de conversão selecionado e no preço em USD, o preço introduzido é muito mais baixo do que o sugerido (%1$s). Este preço vai limitar descontos a até %2$s% para que o preço com desconto não seja inferior a 0,49 $ (USD).`,
  _ = `O preço introduzido é %1$s mais alto do que o preço guardado atualmente.`,
  _ = `O preço introduzido é %1$s mais baixo do que o preço guardado atualmente.`,
  _ = `Um preço assim tão baixo vai limitar descontos a até %1$s% para que o preço com desconto não seja inferior a 0,49 $ (USD).`,
  _ = `Este preço vai limitar descontos a até %1$s% para que o preço com desconto não seja inferior a 0,49 $ (USD).`,
  _ = `NOVO`,
  _ = `Preço publicado:`,
  _ = `Este é o preço atualmente publicado na loja.`,
  _ = `Em análise - Nada a fazer por enquanto`,
  _ = `Em análise - O Steam irá publicar por si`,
  _ = `Análise concluída - Pode agora publicar`,
  _ = `Análise concluída - Pode agora preparar`,
  _ = `Os seus preços foram enviados e estão a aguardar análise. Assim que terminarmos de os analisar, terá de voltar a esta página para os publicar.`,
  _ = `Os seus preços foram enviados e estão a aguardar análise. Assim que terminarmos de os analisar, terá de voltar a esta página para os preparar e assim entrarem em vigor quando o seu jogo for lançado.`,
  _ = `Os seus preços foram enviados e estão a aguardar análise. O Steam irá publicá-los por si assim que a análise tiver terminado, por isso, não é necessária mais nenhuma ação da sua parte.`,
  _ = `Os seus preços foram analisados e estão prontos. Só irão mudar na loja assim que os publicar abaixo.`,
  _ = `Os seus preços foram analisados e estão prontos. Prepare-os abaixo para entrarem em vigor assim que o seu jogo for lançado.`,
  _ = `Preço proposto:`,
  _ = `Este preço foi proposto por %1$s a %2$s e está a aguardar revisão.`,
  _ = `Preço aprovado:`,
  _ = `Este preço foi proposto e revisto. Pode agora ser publicado.`,
  _ = `Preço recomendado:`,
  _ = `Este preço foi recomendado com base num preço em USD de %1$s.`,
  _ = `SELECIONAR`,
  _ = `Clique para propor este preço para revisão.`,
  _ = `Clique para voltar ao preço publicado.`,
  _ = `Reverter todas as alterações não guardadas (%1$s)`,
  _ = `Reverter todas as alterações não guardadas referentes a este pacote`,
  _ = `Cancelar proposta de alteração de preço`,
  _ = `Mostrar apenas pacotes lançados`,
  _ = `Mostrar apenas pacotes não lançados`,
  _ = `A guardar número de pacotes: %1$s`,
  _ = `Preparar novos preços...`,
  _ = `Preparar novos preços?`,
  _ = `Estas %1$s alterações de preços ficarão agora bloqueadas e entrarão em vigor automaticamente assim que o seu jogo for lançado.`,
  _ = `Estas alteração de preço ficará agora bloqueada e entrará em vigor automaticamente assim que o seu jogo for lançado.`,
  _ = `Nada na loja será alterado hoje.`,
  _ = `Preparar agora`,
  _ = `Moeda`,
