  _ = `Destaque principal na página inicial - Imagem estática`,
  _ = `Destaque principal na página inicial - Animação em webm`,
  _ = `Destaque principal na página inicial - Animação em mp4`,
  _ = `Destaque principal na página inicial - Imagem (móvel) `,
  _ = `Destaque principal na página inicial - Animação em webm (móvel)`,
  _ = `Destaque principal na página inicial - Animação em mp4 (móvel)`,
  _ = `Destaque secundário na página inicial - Imagem`,
  _ = `Destaque secundário na página inicial - Imagem (móvel)`,
  _ = `Imagem de fundo de promoção`,
  _ = `Logótipo da página da promoção`,
  _ = `Imagem de capa`,
  _ = `Banner em páginas da loja`,
  _ = `Banner em páginas da loja`,
  _ = `Banner em páginas da loja (móvel)`,
  _ = `Banner em páginas da loja (móvel)`,
