  _ = `Solicitar códigos de Playtest`,
  _ = `Use este formulário para solicitar códigos Steam para o seu pacote de Playtest. Todas as solicitações de códigos Steam são analisadas pela Valve caso a caso, normalmente dentro de 48 a 72 horas.`,
