  _ = `As visitas à página do seu jogo na loja provenientes da página do Next Fest durante o evento. Mostradas apenas para jogos cujo tráfego de marketing pode visualizar.`,
  _ = `Visitas à página do jogo durante o Next Fest`,
  _ = `Todas as visitas à página do seu jogo na loja durante o evento, provenientes de qualquer página do Steam ou da internet. Mostradas apenas para jogos cujo tráfego de marketing pode visualizar.`,
