  _ = `Os seus jogos:`,
  _ = `Mais de (série/developer/editora)`,
  _ = `Nenhuma página de criador foi configurada para a sua aplicação. Consulte a documentação sobre <1>páginas de developers/editoras</1> ou <2>páginas de séries</2> para as configurar.`,
  _ = `Selecione uma página de criador associada cujos produtos pretende apresentar na página do seu jogo na loja. Esta secção irá aparecer por baixo da descrição do jogo.`,
  _ = `Página de criador selecionada:`,
  _ = `Fonte selecionada:`,
  _ = `Ordenar por:`,
  _ = `Selecione a ordem de apresentação de todos os outros artigos não listados como "em destaque" acima.`,
  _ = `Mais vendidos`,
  _ = `Ordenar os jogos mais vendidos primeiro.`,
  _ = `Data de lançamento`,
  _ = `Ordenar os lançamentos mais recentes primeiro. Jogos ainda não lançados irão aparecer primeiro, ordenados pela data de lançamento fornecida.`,
  _ = `Marcadores relevantes`,
  _ = `Ordenar os jogos por semelhança de marcadores com os deste jogo.`,
