  _ = `Não tem permissão para ver o histórico de associações desta aplicação.`,
  _ = `Ainda nenhum nome de developer, editora ou série foi associado a uma página de criador desta aplicação.`,
  _ = `Nome`,
  _ = `Página de criador`,
  _ = `Associado`,
  _ = `Estado`,
  _ = `por %1$s a %2$s`,
  _ = `Ativa`,
  _ = `Removida por %1$s a %2$s`,
  _ = `Desconhecido`,
  _ = `Ocultar associações removidas`,
  _ = `Todas as associações desta aplicação foram removidas.`,
  _ = `Disponível no mundo inteiro`,
