  _ = `Não permitido em: %1$s`,
  _ = `Parece que ainda precisa de preencher o seu <1>inquérito de conteúdo</1>, o qual pode resolver restrições devido à ausência de classificações.`,
  _ = `Gravação de jogos – Gestão de ícones na linha cronológica`,
  _ = `Os ícones criados aqui podem ser referidos a partir do seu jogo para marcar momentos específicos na linha cronológica da gravação do jogo. O Steam também tem um conjunto predefinido de ícones que pode usar. Consulte a documentação para detalhes.`,
  _ = `Criar ícone novo`,
  _ = `Crie um ícone novo que pretende usar na linha cronológica das gravações do seu jogo. `,
  _ = `Criar ícone novo da linha cronológica`,
  _ = `Editar ícone (%1$s)`,
  _ = `Ícone`,
  _ = `Pré‑visualização da linha cronológica:`,
  _ = `Identificador único`,
  _ = `Usado por chamadas à API (%1$s caracteres no máximo)`,
  _ = `O identificador único de ícones públicos não pode ser editado.`,
  _ = `Cor`,
  _ = `introduzir identificador único...`,
  _ = `Usado por chamadas à API (%1$s caracteres no máximo e 3 no mínimo). Tem de ser alfanumérico, em minúsculas. Os caracteres _ e - também são permitidos, mas espaços em branco não.`,
  _ = `O identificador contém caracteres que não são permitidos. Tem de ser alfanumérico, em minúsculas. 3 caracteres no mínimo. Os caracteres _ e - também são permitidos, mas espaços em branco não.`,
  _ = `O identificador não pode começar pela palavra reservada "steam_", usada para ícones oficiais.`,
  _ = `Para cada ícone, envie um .PNG ou um .SVG e forneça um identificador único para ser usado em chamadas da API.`,
  _ = `Ícone (ficheiros .SVG ou .PNG)`,
  _ = `Ícones .SVG serão apresentados numa viewbox de 36\xA0px x\xA036\xA0px. Crie os recursos de acordo com estas dimensões. Imagens .PNG devem ter um formato quadrado, entre 24 e 256\xA0px de largura/altura.`,
  _ = `Ícones .SVG serão apresentados numa viewbox de 36\xA0px x\xA036\xA0px. Crie os recursos de acordo com estas dimensões. Imagens .PNG devem ter um formato quadrado, entre 24 e 256\xA0px de largura/altura.`,
  _ = `Este ficheiro SVG tem uma viewbox ou uma largura/altura de %1$s, o que pode resultar em problemas de apresentação.`,
  _ = `Procure o ficheiro...`,
  _ = `Procure os ficheiros...`,
  _ = `Ou arraste e largue ficheiros aqui`,
  _ = `Visibilidade`,
