  _ = `Erro: o ficheiro .PNG deve ser uma imagem quadrada de, pelo menos, %1$s\xA0px x %1$s\xA0px.`,
  _ = `%1$s ícone pendente`,
  _ = `%1$s ícones pendentes`,
  _ = `Marcadores da linha cronológica novos ou atualizados têm de ser publicados com as outras definições do Steamworks.`,
  _ = `Publicar`,
  _ = `Ícones públicos`,
  _ = `É possível aceder a estes ícones a partir de todos os ramos, incluindo o ramo padrão (default) por chamadas à API.`,
  _ = `Por serem ícones públicos, estes podem ser referidos noutros locais e não é possível eliminá‑los nem mudar o nome. Pode atualizar a imagem, se necessário.`,
  _ = `Crie ícones novos como "públicos" caso pretenda prepará‑los para o lançamento público.`,
  _ = `Ícones ocultos`,
  _ = `Use ícones ocultos para os testar antes de terem visibilidade pública. Use os conjuntos abaixo para associar ícones específicos a ramos específicos se precisar de limitar o acesso.`,
  _ = `Use ícones ocultos para testes antes de os tornar visíveis.`,
  _ = `Por designar`,
  _ = `Estes ícones não irão aparecer em nenhuma build`,
  _ = `Tornar públicos todos os marcadores ocultos`,
  _ = `Transferir para testes locais`,
  _ = `Cria um único ficheiro .SVG que o Steam pode usar para gerar os ícones. Esta ação irá criar um ficheiro com todos os ícones públicos e os ícones no conjunto oculto.`,
  _ = `Crie ícones novos como "ocultos" caso pretenda testá‑los antes de os tornar públicos.`,
  _ = `Limitado aos ramos: `,
  _ = `Nenhum ramo selecionado`,
  _ = `Criar novo conjunto de ramos`,
  _ = `Conjuntos de ramos ajudam a gerir o teste de ícones ocultos, permitindo que sejam acessíveis apenas por builds em ramos específicos.`,
  _ = `Conjunto de ramos sem título %1$s`,
  _ = `Restringidos por ramo`,
  _ = `Limite ícones para que sejam visíveis apenas em ramos de builds selecionados.`,
  _ = `Conjunto de ramos: %1$s`,
  _ = `Editar ramos`,
  _ = `Publicar ramo`,
  _ = `Clonar marcador da linha cronológica`,
  _ = `Selecione um marcador publicado da lista abaixo para clonar para o conjunto de ramos %1$s. Exclui marcadores que já estejam nesse conjunto de ramos.`,
  _ = `Marcador da linha cronológica clonado com sucesso. `,
  _ = `(Opcional) Selecione um ou mais ramos com os quais associar estes itens. Os utilizadores com acesso aos ramos selecionados poderão ver os recursos. Se selecionar um ramo não protegido por palavra-passe, os ícones serão considerados publicamente visíveis.`,
  _ = `Não foram efetuadas alterações à lista de ramos.`,
