  _ = `Publicação pendente`,
  _ = `Ficheiros de marcadores publicados`,
  _ = `Os conjuntos de ramos e ícones públicos acima podem fornecer marcadores da linha cronológica específicos para os ramos seguintes. Se um conjunto de ramos não tiver ícones publicados, então os respetivos ramos não irão contribuir:`,
  _ = `Estes conjuntos de ramos não têm um ficheiro público específico. Os utilizadores destes ramos irão usar os marcadores da linha cronológica do ramo padrão (default).`,
  _ = `dummy`,
  _ = `Proezas`,
  _ = `%1$s%`,
  _ = `Conjuntos de proezas`,
  _ = `Use conjuntos para gerir restrições de acesso e visibilidade de proezas. Por exemplo, pode querer um conjunto de proezas que só está disponível para proprietários de um determinado DLC.`,
  _ = `Vista Geral`,
  _ = `Design`,
  _ = `Requisitos`,
  _ = `Lançamento`,
  _ = `Teste`,
  _ = `Defina e atualize as proezas do seu jogo.`,
  _ = `Para obter os melhores resultados, os ícones de proezas devem ser imagens PNG com as dimensões de 256\xA0x\xA0256 pixels. As dimensões mínimas permitidas são de 64x64, mas é recomendado que use as dimensões maiores. Recomendamos que os ícones de proezas alcançadas estejam a cores e os ícones de proezas por alcançar estejam a preto e branco.`,
  _ = `Como as proezas Steam podem aparecer em vários locais na Comunidade Steam, os nomes e ícones que usar devem ser apropriados para todas as idades e públicos. A Valve pode remover da loja os jogos que violarem as <1>diretrizes de conteúdo da comunidade</1> ou que sejam ofensivos.`,
  _ = `Para ativar proezas por completo e para concluir a lista de tarefas para o lançamento, também terá de selecionar a opção correspondente na secção <1>Funcionalidades suportadas</1> do separador "Informações básicas" no painel de administração da sua página na loja.`,
  _ = `Antes do lançamento, <1>pode pré-visualizar as suas proezas aqui</1>. O estado de lançamento das proezas será mostrado na página.`,
