  _ = `Ficheiros CSV para definições e tradução de proezas. Use os botões à direita para fazer o download dos modelos para os ficheiros CSV necessários. As notas em parênteses na linha do cabeçalho são instruções e são ignoradas quando envia o ficheiro.`,
